/* מעדכן את סמל הפרופיל: אווטאר נבחר > תמונת Google > מעטפה/✕ */
function refreshProfilePhoto() {
  const el = $("#profile-photo"); if (!el || !currentUser) return;
  if (myAvatar && avatarSrc(myAvatar)) el.src = avatarSrc(myAvatar);
  else if (currentUser.isAnonymous) el.src = PH_X;
  else if (currentUser.photoURL) el.src = currentUser.photoURL;
  else el.src = PH_MAIL;
}

function renderAvatarChoices() {
  const box = $("#avatar-choices"); if (!box) return;
  box.innerHTML = "";
  AVATARS.forEach(({ id, src }) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "avatar-choice photo" + (myAvatar === id ? " selected" : "");
    b.innerHTML = `<img src="${src}" alt="">`;
    b.addEventListener("click", () => {
      myAvatar = id;
      if (currentUser) update(ref(db, "users/" + currentUser.uid + "/profile"), { gameAvatar: id });
      renderAvatarChoices();
      refreshProfilePhoto();
      toast("האווטאר נבחר ✓");
    });
    box.appendChild(b);
  });
}

const NAV_SCREENS = ["screen-home", "screen-profile", "screen-apps"];

function showScreen(id) {
  $$(".screen").forEach(s => s.classList.remove("active"));
  $("#" + id).classList.add("active");
  document.body.classList.toggle("nav-visible", NAV_SCREENS.includes(id));
  const map = { "screen-home": "home", "screen-profile": "profile", "screen-apps": "apps" };
  $$(".nav-btn").forEach(b => b.classList.toggle("active", b.dataset.nav === map[id]));
  window.scrollTo(0, 0);
}
